import { useState, useRef, useEffect } from 'react';

// FIX 1: div acting as button
function ToggleButton({ onToggle, label }) {
  return (
    // TODO: make this keyboard accessible and screen reader friendly
    <div onClick={onToggle} data-testid="toggle">
      {label}
    </div>
  );
}

// FIX 2: input with no label
function SearchInput({ value, onChange }) {
  return (
    // TODO: add a label or aria-label
    <input
      data-testid="search"
      type="text"
      value={value}
      onChange={onChange}
    />
  );
}

// FIX 3: error message not announced
function ValidationError({ message }) {
  if (!message) return null;
  // TODO: make this announce to screen readers
  return <p data-testid="error">{message}</p>;
}

export default function App() {
  const [on, setOn] = useState(false);
  const [search, setSearch] = useState('');
  const [error] = useState('Quest title is required');
  return (
    <div>
      <ToggleButton onToggle={() => setOn(!on)} label={on ? 'On' : 'Off'} />
      <SearchInput value={search} onChange={e => setSearch(e.target.value)} />
      <ValidationError message={error} />
    </div>
  );
}
